<?php
namespace App\Notifications;
use App\Models\Appointment; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class AppointmentConfirmed extends Notification { use Queueable; public function __construct(private Appointment $appointment){} public function via(object $notifiable): array{return ['mail','database'];} public function toMail(object $notifiable): MailMessage { $local=$this->appointment->starts_at->setTimezone($this->appointment->provider->timezone);return (new MailMessage)->subject('Appointment confirmed')->greeting('Hello '.$notifiable->name)->line('Your appointment has been confirmed.')->line('Service: '.$this->appointment->service->name)->line('Provider: '.$this->appointment->provider->user->name)->line('Time: '.$local->format('Y-m-d H:i').' '.$this->appointment->provider->timezone); } public function toArray(object $notifiable): array{return ['appointment_id'=>$this->appointment->id,'type'=>'confirmed','starts_at'=>$this->appointment->starts_at->toIso8601String()];} }
